        assertEquals("", mensajes(c886), "rechazo-por-saldo-insuficiente-de-dos-aportes-del-mismo-portafolio-rechaza-a-los-dos-y-sale-por-la-salida-temprana :: messages of the output");
        assertEquals("COMMIT", decision(c886), "rechazo-por-saldo-insuficiente-de-dos-aportes-del-mismo-portafolio-rechaza-a-los-dos-y-sale-por-la-salida-temprana :: decision of the host");
